    private const PREVIOUS_ACCOUNTING_BODY_EN = '<h2>Know where the business stands</h2><p>Track every transaction with linked entries, account statements, approvals and reliable balance sheet, profit and loss, trial balance and cash-flow reports.</p>';

    public function run(): void
    {
        $this->upgradeAccountingStarter();

        foreach ([$this->grantManagement(), $this->monitoringEvaluation(), $this->beneficiaryManagement()] as $page) {
            ContentPage::query()->firstOrCreate(['slug' => $page['slug']], $page);
        }
    }

    private function upgradeAccountingStarter(): void
    {
        $attributes = $this->accounting();
        $page = ContentPage::query()->where('slug', $attributes['slug'])->first();

        if (! $page) {
            ContentPage::query()->create($attributes);

            return;
        }

        // Upgrade only the known starter. Content maintained through the CMS remains authoritative.
        if ($page->translation('body', 'en') !== self::PREVIOUS_ACCOUNTING_BODY_EN) {
            return;
        }

        $page->update(collect($attributes)->except(['type', 'slug', 'status', 'published_at'])->all());
    }

